//! Unapplied EB ABI4 transport diagnostic; deliberately not a dynamic-eval API.
mod wasmtime_policy;
mod wasmtime_config;
mod embedded_runtime;

use lila_aot_wasm::{
    emit_with_intl_profile_and_runtime_inputs, GcSnapshotField as F,
    PromiseRejectionPolicy, RuntimeArtifact, RuntimeArtifactCache,
    RuntimeArtifactCacheKey, WasmArtifact, WasmRuntimeValueTag as Tag,
    RUNTIME_IMPORT_NAMESPACE,
};
use lila_ir::CompletionKindIr as Kind;
use std::sync::Arc;
use wasmtime::{
    ArrayRef, ArrayRefPre, AsContextMut, Caller, Engine, Error, ExternType,
    Func, GcHeapOutOfMemory, Instance, Linker, Memory, Module, Result, Rooted,
    SharedMemory, Store, StoreLimits, StoreLimitsBuilder, StructRef, StructRefPre,
    StructType, Val, WasmBacktraceDetails,
};

const P1: &str = r#"
(function receive(candidate) {
    "use strict";
    if (candidate === undefined) { print("compile-now"); return 17; }
    if (candidate === 0) { return Function("return 17;")(); }
    return candidate(40);
});
"#;
const P2: &str = r#"(function second(x) { "use strict"; return x + 2; });"#;
const P2_CONFLICT: &str = r#"
if (false) { Function("return 23;"); }
(function second(x) { "use strict"; return x + 2; });
"#;

// build_package::load_or_emit consults this only after rejecting the embedded
// package. Panic at that boundary prevents any raw-R emission fallback.
struct BundleOnly;
impl RuntimeArtifactCache for BundleOnly {
    fn compiler_identity(&self) -> &[u8; 32] { panic!("NO-GO: embedded raw R was not admitted") }
    fn load(&self, _: RuntimeArtifactCacheKey) -> Option<Vec<u8>> { unreachable!() }
    fn store(&self, _: RuntimeArtifactCacheKey, _: Vec<u8>) -> bool { unreachable!() }
    fn remove(&self, _: RuntimeArtifactCacheKey) { unreachable!() }
}
static BUNDLE_ONLY: BundleOnly = BundleOnly;

struct State {
    limits: StoreLimits,
    monotonic_origin: std::time::Instant,
    linker: Option<Linker<State>>,
    runtime: Option<Arc<RuntimeArtifact>>,
    memory: Option<Memory>,
    receive: Option<Rooted<StructRef>>,
    call: Option<Func>,
    conflict: bool,
    entered: bool,
    transported: bool,
}

fn require(ok: bool, message: &str) -> Result<()> {
    if ok { Ok(()) } else { Err(Error::msg(message.to_owned())) }
}

fn emit(source: &str) -> Result<WasmArtifact> {
    let parsed = lila_front::parse(source, lila_front::ParseOptions::script())?;
    let program = lila_ir::lower(&parsed);
    Ok(emit_with_intl_profile_and_runtime_inputs(
        &program, PromiseRejectionPolicy::FailRun,
        &lila_intl::IntlCompilationProfile::Minimal,
        embedded_runtime::inputs(Some(&BUNDLE_ONLY)),
    )?)
}

// Same declaration/name lookup already used by runtime_regexp_compiler_tests.
fn helper_export(bytes: &[u8], helper: &str) -> Result<String> {
    for payload in wasmparser::Parser::new(0).parse_all(bytes) {
        let wasmparser::Payload::CustomSection(section) = payload? else { continue };
        let wasmparser::KnownCustom::Name(names) = section.as_known() else { continue };
        for subsection in names {
            if let wasmparser::Name::Function(names) = subsection? {
                for entry in names {
                    let entry = entry?;
                    if entry.name == helper { return Ok(format!("f{}", entry.index)); }
                }
            }
        }
    }
    Err(Error::msg(format!("no physical {helper} export")))
}

fn results<S: AsContextMut<Data = State>>(cx: &mut S, f: Func, args: &[Val]) -> Result<Vec<Val>> {
    let mut output = f.ty(cx.as_context()).results()
        .map(|ty| Val::default_for_ty(&ty).ok_or_else(|| Error::msg("non-defaultable completion")))
        .collect::<Result<Vec<_>>>()?;
    require(output.len() == 5, "expected actual five-slot Completion")?;
    f.call(&mut *cx, args, &mut output)?;
    Ok(output)
}

fn structure<S: AsContextMut<Data = State>>(cx: &S, value: Val) -> Result<Rooted<StructRef>> {
    let Val::AnyRef(Some(value)) = value else { return Err(Error::msg("expected rooted GC reference")) };
    value.as_struct(cx.as_context())?.ok_or_else(|| Error::msg("expected actual GC struct"))
}

fn field<S: AsContextMut<Data = State>>(cx: &mut S, value: Rooted<StructRef>, f: F) -> Result<Val> {
    value.field(&mut *cx, f.index() as usize)
}

fn main_function<S: AsContextMut<Data = State>>(cx: &mut S, instance: Instance) -> Result<Rooted<StructRef>> {
    let main = instance.get_func(&mut *cx, "main").ok_or_else(|| Error::msg("missing main"))?;
    let value = results(cx, main, &[])?;
    let kind = lila_aot_wasm::check_gc_main_completion(value[3].unwrap_i32(), value[4].unwrap_i32())
        .map_err(Error::msg)?;
    require(kind == Kind::Normal && value[0].unwrap_i32() == Tag::Function.tag(),
        &format!("main did not return FunctionObject: {value:?}"))?;
    structure(cx, value[2])
}

// Use the existing R ProxyCall helper, not a new callable wrapper or a copied
// ten-argument ordinary-body ABI. All arrays/StoredValues derive from its actual
// canonical signature and declaration-owned public field witnesses.
fn invoke<S: AsContextMut<Data = State>>(
    cx: &mut S, call: Func, callee: Rooted<StructRef>, argument: Option<[Val; 3]>,
) -> Result<Vec<Val>> {
    let context_value = field(cx, callee, F::FunctionContext)?;
    let context = structure(cx, context_value)?;
    let realm_value = field(cx, context, F::ContextRealm)?;
    let signature = call.ty(cx.as_context());
    let params: Vec<_> = signature.params().collect();
    require(params.len() == 9, "R ProxyCall ABI changed")?;
    let array_ty = params[6].unwrap_ref().heap_type().unwrap_concrete_array().clone();
    let stored_ty = array_ty.element_type().unwrap_val_type().unwrap_ref()
        .heap_type().unwrap_concrete_struct().clone();
    let mut entries = Vec::new();
    if let Some(argument) = argument {
        require(stored_ty.fields().len() == 3, "StoredValue schema changed")?;
        let mut fields = vec![Val::I32(0); stored_ty.fields().len()];
        fields[F::StoredTag.index() as usize] = argument[0];
        fields[F::StoredScalar.index() as usize] = argument[1];
        fields[F::StoredRef.index() as usize] = argument[2];
        let pre = StructRefPre::new(&mut *cx, stored_ty);
        entries.push(Val::from(StructRef::new(&mut *cx, &pre, &fields)?));
    }
    let pre = ArrayRefPre::new(&mut *cx, array_ty);
    let argv = ArrayRef::new_fixed(&mut *cx, &pre, &entries)?;
    results(cx, call, &[
        Val::I32(Tag::Function.tag()), Val::I64(0), Val::from(callee),
        Val::I32(Tag::Undefined.tag()), Val::I64(0), Val::AnyRef(None),
        Val::from(argv), realm_value, Val::AnyRef(None),
    ])
}

fn number(value: f64) -> [Val; 3] {
    [Val::I32(Tag::Number.tag()), Val::I64(value.to_bits() as i64), Val::AnyRef(None)]
}

fn expect_return(value: &[Val], number: f64, stage: &str) -> Result<()> {
    // ProxyCall forwards the source body's Return. Normalization/restoration is
    // owned by its real Wasm Call caller; the host diagnostic does neither.
    require(value[0].unwrap_i32() == Tag::Number.tag()
        && value[1].unwrap_i64() == number.to_bits() as i64
        && matches!(value[2], Val::AnyRef(None))
        && i64::from(value[3].unwrap_i32()) == Kind::Return.abi_code()
        && value[4].unwrap_i32() == 0,
        &format!("NO-GO {stage}: expected Return({number}), got {value:?}"))
}

fn nested(mut caller: Caller<'_, State>, inputs: &[Val], outputs: &mut [Val]) -> Result<()> {
    require(inputs.len() == 2 && outputs.is_empty(), "print ABI changed")?;
    let (mut linker, runtime, receive, call, memory, conflict) = {
        let state = caller.data();
        require(!state.entered, "unexpected recursive print callback")?;
        (state.linker.clone().ok_or_else(|| Error::msg("callback before arm"))?,
         state.runtime.clone().unwrap(), state.receive.unwrap(), state.call.unwrap(),
         state.memory.unwrap(), state.conflict)
    }; // All data() borrows end before instantiation/calls borrow &mut Caller.
    let length = usize::try_from(inputs[1].unwrap_i32())?;
    require(length == b"compile-now".len(), "unexpected print trigger length")?;
    let mut marker = vec![0; length];
    memory.read(&caller, usize::try_from(inputs[0].unwrap_i32())?, &mut marker)?;
    require(marker == b"compile-now", "unexpected print trigger bytes")?;
    caller.data_mut().entered = true;

    let artifact = emit(if conflict { P2_CONFLICT } else { P2 })?;
    let next_runtime = artifact.runtime().ok_or_else(|| Error::msg("P2 is not linked"))?;
    require(next_runtime.key() == runtime.key() && next_runtime.bytes() == runtime.bytes(),
        "P2 selected different R")?;
    if conflict {
        require(artifact.function_sizes.iter().any(|f| f.name == "helper::prepared_dynamic_function"),
            "inconclusive conflict fixture: P2 did not retain prepared Function hook")?;
    }
    let module = Module::new(caller.engine(), &artifact.bytes)?; // P2 only, never R.
    link_hosts(&mut caller, &mut linker, &module)?;
    let instance = linker.instantiate(&mut caller, &module)?;
    let second = main_function(&mut caller, instance)?;
    require(StructType::eq(&receive.ty(&caller)?, &second.ty(&caller)?),
        "NO-GO: independently emitted P FunctionObject types did not canonicalize")?;
    caller.gc(None)?;
    let value = invoke(&mut caller, call, receive,
        Some([Val::I32(Tag::Function.tag()), Val::I64(0), Val::from(second)]))?;
    expect_return(&value, 42.0, "reentrant typed-GC invocation")?;
    caller.data_mut().transported = true;
    println!("reentrant-typed-GC-call=42");
    Ok(())
}

fn link_hosts<S: AsContextMut<Data = State>>(
    cx: &mut S, linker: &mut Linker<State>, module: &Module,
) -> Result<()> {
    for import in module.imports() {
        if import.module() == RUNTIME_IMPORT_NAMESPACE
            || linker.try_get_by_import(&mut *cx, &import)?.is_some() { continue; }
        match import.ty() {
            ExternType::Memory(ty) if ty.is_shared() => {
                let memory = SharedMemory::new(cx.as_context().engine(), ty)?;
                linker.define(&mut *cx, import.module(), import.name(), memory)?;
            }
            ExternType::Memory(ty) => {
                let memory = Memory::new(&mut *cx, ty)?;
                linker.define(&mut *cx, import.module(), import.name(), memory)?;
            }
            ExternType::Func(signature) => {
                let name = format!("{}::{}", import.module(), import.name());
                let byte_array = if name == "lila_host::byte_array_allocate" {
                    Some(signature.results().next().ok_or_else(|| Error::msg("missing byte-array result"))?
                        .unwrap_ref().heap_type().unwrap_concrete_array().clone())
                } else { None };
                linker.func_new(import.module(), import.name(), signature, move |mut caller, inputs, outputs| {
                    match name.as_str() {
                        "lila_host::print_line_utf8" => nested(caller, inputs, outputs),
                        "lila_host::collect_gc" => caller.gc(None),
                        "lila_host::weak_job_finish" => {
                            // Engine clears kept roots and resets its poll cursor here.
                            // This fresh diagnostic host permits no weak allocation,
                            // dereference or registry operation: all trap below, so
                            // its kept set and cursor remain empty/zero throughout.
                            require(inputs.is_empty() && outputs.is_empty(), "weak job finish ABI changed")
                        }
                        "lila_host::finalization_next_registry" => {
                            // The real host returns None when its registry vector
                            // is empty. Registry creation/registration traps here.
                            require(inputs.is_empty() && outputs.len() == 1, "finalization registry ABI changed")?;
                            outputs[0] = Val::AnyRef(None);
                            Ok(())
                        }
                        "lila_host::monotonic_clock_nanos" => {
                            require(inputs.is_empty() && outputs.len() == 1, "monotonic clock ABI changed")?;
                            let nanos = caller.data().monotonic_origin.elapsed().as_nanos();
                            outputs[0] = Val::I64(nanos.min(i64::MAX as u128) as i64);
                            Ok(())
                        }
                        "lila_host::agent_can_suspend" => { outputs[0] = Val::I32(0); Ok(()) }
                        "lila_host::byte_array_allocate" => {
                            let length = u32::try_from(inputs[0].unwrap_i32())?;
                            let pre = ArrayRefPre::new(&mut caller, byte_array.as_ref().unwrap().clone());
                            outputs[0] = match ArrayRef::new(&mut caller, &pre, &Val::I32(0), length) {
                                Ok(value) => Val::from(value),
                                Err(error) if error.is::<GcHeapOutOfMemory<()>>() => Val::AnyRef(None),
                                Err(error) => return Err(error),
                            };
                            Ok(())
                        }
                        _ => Err(Error::msg(format!("unimplemented proof host callback executed: {name}"))),
                    }
                })?;
            }
            other => return Err(Error::msg(format!("unexpected proof import: {other:?}"))),
        }
    }
    Ok(())
}

fn run(conflict: bool) -> Result<()> {
    let mode = wasmtime_config::WasmNativeCompilationMode::Fast;
    let mut config = wasmtime_config::base_config(mode, WasmBacktraceDetails::Disable);
    config.parallel_compilation(false);
    let engine = Engine::new(&config)?;
    wasmtime_policy::PRODUCT_WASMTIME_POLICY.verify_engine(&engine).map_err(Error::msg)?;
    let artifact = emit(P1)?;
    let runtime = artifact.runtime().ok_or_else(|| Error::msg("P1 is not linked"))?.clone();
    // Existing immutable Cargo leaf admission. No arbitrary native slice/path
    // enters this call and a miss is a hard stop, never Module::new(R).
    let r = embedded_runtime::load_native(&engine, &runtime, mode)
        .ok_or_else(|| Error::msg("NO-GO: existing embedded native R not admitted"))?;
    let p = Module::new(&engine, &artifact.bytes)?;
    let call_export = helper_export(runtime.bytes(), "helper::proxy_call")?;
    let mut store = Store::new(&engine, State {
        limits: StoreLimitsBuilder::new().memory_size(1024 * 1024 * 1024).build(),
        monotonic_origin: std::time::Instant::now(),
        linker: None, runtime: None, memory: None, receive: None, call: None,
        conflict, entered: false, transported: false,
    });
    store.limiter(|state| &mut state.limits);
    store.set_epoch_deadline(u64::MAX / 2);
    let mut linker = Linker::new(&engine);
    link_hosts(&mut store, &mut linker, &r)?;
    let r_instance = linker.instantiate(&mut store, &r)?;
    linker.instance(&mut store, RUNTIME_IMPORT_NAMESPACE, r_instance)?;
    link_hosts(&mut store, &mut linker, &p)?;
    let p_instance = linker.instantiate(&mut store, &p)?;
    let receive = main_function(&mut store, p_instance)?;
    let call = r_instance.get_func(&mut store, &call_export).ok_or_else(|| Error::msg("missing ProxyCall"))?;
    let before = invoke(&mut store, call, receive, Some(number(0.0)))?;
    expect_return(&before, 17.0, "baseline old P Function hook")?;
    println!("baseline-old-P=17");
    let memory = r_instance.get_memory(&mut store, "memory").ok_or_else(|| Error::msg("missing R memory"))?;
    {
        let state = store.data_mut();
        state.linker = Some(linker); state.runtime = Some(runtime);
        state.memory = Some(memory); state.receive = Some(receive); state.call = Some(call);
    }
    let outer = invoke(&mut store, call, receive, None)?;
    expect_return(&outer, 17.0, "old P resume after host callback")?;
    require(store.data().entered && store.data().transported, "callback transport was not executed")?;
    println!("outer-P-resumed=17");
    let after = invoke(&mut store, call, receive, Some(number(0.0)))?;
    expect_return(&after, 17.0, "old P hook context after P2 main")?;
    println!("old-P-hook-context=17");
    println!("transport-only diagnostic completed; source-proven shared-P ownership hazards remain");
    Ok(())
}

fn worker(conflict: bool) -> Result<()> {
    std::thread::Builder::new().stack_size(wasmtime_config::ENGINE_WORKER_STACK_SIZE)
        .spawn(move || run(conflict))?.join().map_err(|_| Error::msg("diagnostic worker panicked"))?
}

#[test]
fn transport() {
    worker(false).expect("same-Store reentrant typed-GC transport");
}

#[test]
fn conflict() {
    worker(true).expect("old P prepared Function context before/after P2 main");
}

fn main() -> Result<()> {
    let conflict = match std::env::args().nth(1).as_deref() {
        Some("transport") => false,
        Some("conflict") => true,
        _ => return Err(Error::msg("usage: probe <transport|conflict>")),
    };
    worker(conflict)
}

